import { Quote } from 'lucide-react';
import type { HTMLAttributes, ReactNode } from 'react';
import { cn } from '../../utils/cn';
import { blockquoteVariants, type BlockquoteVariantProps } from './blockquote.variants';

export interface BlockquoteProps extends Omit<HTMLAttributes<HTMLElement>, 'className'>, BlockquoteVariantProps {
  className?: string;
  /** The quoted content. */
  children: ReactNode;
  /** Who said or wrote it (rendered in a `<cite>`). */
  source?: ReactNode;
  /** Role, company or publication shown after the source. */
  sourceDetail?: ReactNode;
  /** URL of the original; sets the blockquote `cite` attribute and links the source. */
  cite?: string;
  /** Leading media in the caption, e.g. an Avatar. */
  avatar?: ReactNode;
  /** Show a decorative quote mark (default on for the card and pull variants). */
  showMark?: boolean;
}

/**
 * Quoted content with its attribution: a `<figure>` holding the `<blockquote>` and a
 * `<figcaption>` whose `<cite>` names the source (linked when `cite` is a URL).
 */
export function Blockquote({ variant = 'default', className, children, source, sourceDetail, cite, avatar, showMark, ...props }: BlockquoteProps) {
  const s = blockquoteVariants({ variant });
  const mark = showMark ?? variant !== 'default';
  const hasCaption = source != null || sourceDetail != null;
  return (
    <figure className={cn(s.root(), className)} {...props}>
      {mark && <Quote size={variant === 'pull' ? 22 : 18} aria-hidden className={cn(s.mark(), variant === 'pull' ? 'mx-auto mb-3' : 'mb-2.5')} />}
      <blockquote cite={cite} className={s.quote()}>
        {children}
      </blockquote>
      {hasCaption && (
        <figcaption className={s.caption()}>
          {avatar && <span className={s.avatar()}>{avatar}</span>}
          <span className={s.source()}>
            {source != null && (
              <cite className={s.name()}>
                {cite ? (
                  <a href={cite} className={s.link()}>
                    {source}
                  </a>
                ) : (
                  source
                )}
              </cite>
            )}
            {sourceDetail != null && <span className={s.detail()}>{sourceDetail}</span>}
          </span>
        </figcaption>
      )}
    </figure>
  );
}

import { tv, type VariantProps } from '../../utils/tv';

export const blockquoteVariants = tv({
  slots: {
    root: 'm-0 min-w-0',
    quote: 'm-0 text-foreground text-pretty',
    mark: 'shrink-0 text-primary-text',
    caption: 'mt-3 flex min-w-0 items-center gap-2.5 text-[12.5px] text-muted-foreground',
    avatar: 'shrink-0',
    source: 'flex min-w-0 flex-col',
    name: 'truncate font-semibold text-foreground not-italic',
    detail: 'truncate',
    link: 'underline underline-offset-2 hover:text-foreground focus-visible:rounded-sm focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
  },
  variants: {
    variant: {
      /** Inline-start rule, for quotes inside prose. */
      default: { root: 'border-s-2 border-primary/70 ps-4', quote: 'text-[14px] leading-6' },
      /** A card for testimonials and feedback. */
      card: { root: 'rounded-xl border border-border bg-card p-5 shadow-sm', quote: 'text-[14px] leading-6' },
      /** Large, centred pull quote for editorial pages. */
      pull: { root: 'mx-auto max-w-2xl text-center', quote: 'text-[19px] leading-8 font-medium tracking-tight', caption: 'justify-center' },
    },
  },
  defaultVariants: { variant: 'default' },
});

export type BlockquoteVariantProps = VariantProps<typeof blockquoteVariants>;

export { Blockquote, type BlockquoteProps } from './Blockquote';
export { blockquoteVariants, type BlockquoteVariantProps } from './blockquote.variants';
export { doc as blockquoteDoc } from './Blockquote.doc';

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Blockquote',
  group: 'Display',
  status: 'beta',
  description:
    'Quoted content with its citation: a figure with the blockquote and a figcaption whose cite names the source (linked when `cite` is a URL). Variants: an inline-start rule for prose, a card for testimonials, a centred pull quote.',
  pattern: 'figure + blockquote + figcaption/cite',
  keyboard: [['Tab', 'Moves to the source link when `cite` is set']],
  tokens: ['primary', 'primary-text', 'card', 'border', 'foreground', 'muted-foreground', 'focus-ring'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
